questionvariables.text:
/* exd: shortest exact decimal display of a terminating value (up to 3 d.p.) */
exd(v) := if integerp(v) then v else if integerp(10*v) then dispdp(float(v),1) else if integerp(100*v) then dispdp(float(v),2) else dispdp(float(v),3);
/* Design: find-the-mistake pattern for an ogive. er 1: frequencies at upper boundaries; er 2: cf at midpoints; er 3: cf at lower boundaries. Source: adapted from SMP AS/A2 Statistics 1, chapter 1, section D. */
flist: [[2,8,11,12,11,2],[2,2,12,12,15,11],[7,7,11,13,9,9],[14,11,7,6,6,2],[3,5,8,11,10,6],[2,10,14,7,7,6],[3,5,11,4,4,3],[6,6,10,15,2,2],[3,6,7,12,4,3],[4,6,8,11,6,6]];
ix: 1+rand(10);
f: flist[ix];
lo1: rand([10,20]);
er: rand([1,2,3]);
j: 2+rand(4);
w: 10;
lo: makelist(lo1+(t-1)*w,t,1,6);
hi: makelist(lo1+t*w-1,t,1,6);
cf: makelist(sum(f[i],i,1,t),t,1,6);
n: cf[6];
lcb1: lo1-1/2;
ucb: makelist(lo1+t*w-1/2,t,1,6);
mid: makelist(lo1+(t-1)*w+(w-1)/2,t,1,6);
lcb: makelist(lo1+(t-1)*w-1/2,t,1,6);
ucbj: ucb[j];
jx: float(if er=1 then append([lcb1],ucb) elseif er=2 then append([lcb1-5],mid) else append([lcb1-10],lcb));
jy: if er=1 then append([0],f) else append([0],cf);
xmax: lo1+70;
ymax: 2*ceiling(n/2);
xlab: if lo1=10 then "Mark" else "Mass (kg)";
opts: [["o1",false,"He joined the points with straight lines instead of a smooth curve."],["o2",is(er=1),"He plotted the frequencies instead of the cumulative frequencies."],["o3",is(er=2),"He plotted each cumulative frequency at the class midpoint instead of the upper class boundary."],["o4",is(er=3),"He plotted each cumulative frequency at the lower class boundary instead of the upper class boundary."]];
wr1: if er=2 then "o4" else "o3";
/* diagnostics */
midj: mid[j];
lcbj: lcb[j];
hij: hi[j];
ucbp: ucbj+2;
